   (0x800b380a, [249; 249])].

Fixpoint runs_lookup (runs : list (Z * list Z)) (g : Z) : Z :=
  match runs with
  | [] => 0
  | (lo, bs) :: r => if (lo <=? g) && (g <? lo + Z.of_nat (length bs)) then nth (Z.to_nat (g - lo)) bs 0 else runs_lookup r g
  end.
(* [comment removed for export] *)
Definition alowsh (g : Z) : Z := runs_lookup ALOWSH_RUNS g.

Definition alink_val (a : Z) : option Z :=
  match find (fun p => fst p =? a) ALINK_WORDS with Some p => Some (snd p) | None => None end.

Lemma alink_val_In : forall a v, alink_val a = Some v -> In (a, v) ALINK_WORDS.
Proof.
  intros a v H. unfold alink_val in H. destruct (find (fun p => fst p =? a) ALINK_WORDS) as [[a' v']|] eqn:E; [|discriminate].
  injection H as <-. apply find_some in E. destruct E as [Hin Hb]. cbn in Hb. apply Z.eqb_eq in Hb. subst a'. exact Hin.
Qed.

